#!/usr/bin/env python3
"""Generate .claude/agents/mission-lock-eval-runner.md (do not edit that file by hand).

The runner embeds SKILL.md and the files it points at (definitions/*.md
and assets/report-template.md) in the agent's system prompt, so parallel eval
subagents share one cacheable prefix instead of each re-reading the skill.

Regenerate whenever anything under skills/mission-lock/ changes:
    python3 evals/build_bundled_runner.py
"""
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent
SKILL_DIR = REPO_ROOT / "skills" / "mission-lock"
OUT = REPO_ROOT / ".claude" / "agents" / "mission-lock-eval-runner.md"

BUNDLED = [
    "SKILL.md",
    *sorted(str(p.relative_to(SKILL_DIR)) for p in (SKILL_DIR / "definitions").glob("*.md")),
    "assets/report-template.md",
]

HEADER = """---
name: mission-lock-eval-runner
description: with-skill eval runner for the Mission Lock Analyzer eval suite, with the skill and its reference files bundled into the system prompt and a fixed model and effort to keep benchmarks consistent. Generated by evals/build_bundled_runner.py; do not edit by hand. Only used for explicit eval runs (see evals/CLAUDE.md and evals/benchmarks/README.md).
model: sonnet
effort: medium
tools: Read, Bash, Grep, Glob
---

You are acting as the "Mission Lock Analyzer" (MLA) Claude Code skill, exactly as a real end user invoking it would experience it, for an eval run in the mission-lock repo.

The full skill (SKILL.md) and every reference/asset file it points to are included verbatim below. Treat them as already read: do NOT re-read them from disk, and treat any relative path in SKILL.md as pointing at the embedded copy. The one exception is assets/report-template.html, which is not embedded; read skills/mission-lock/assets/report-template.html from disk only if the task asks for an HTML report.

For the eval task given to you in the prompt, do this:

1. Follow SKILL.md's instructions exactly.
2. Read the document file(s) specified in the task in full.
3. Respond to the user request given in the task exactly as the skill instructs, producing the complete report as the deliverable.
4. Your FINAL MESSAGE must contain ONLY the complete, verbatim Markdown report text itself, followed by a line "TOOL_USE_COUNT: N". Do NOT summarize what you did or describe the report: paste the report text directly into your final message.
"""

def main():
    parts = [HEADER]
    for rel in BUNDLED:
        parts.append(f"\n=== BEGIN FILE: {rel} ===\n{(SKILL_DIR / rel).read_text()}\n=== END FILE: {rel} ===\n")
    OUT.write_text("".join(parts))
    print(f"wrote {OUT.relative_to(REPO_ROOT)} ({OUT.stat().st_size} bytes; {len(BUNDLED)} files)")

if __name__ == "__main__":
    main()
